1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Computes a single Luhn check digit (0-9) over the digits contained in a
5	 * string, ignoring any non-digit characters.
6	 */
7	final class CheckDigits {
8	
9	    private CheckDigits() {
10	    }
11	
12	    /** Luhn check digit (0-9) over the digits contained in {@code s}. */
13	    static int luhnOf(String s) {
14	        int sum = 0;
15	        boolean dbl = true;
16	        for (int i = s.length() - 1; i >= 0; i--) {
17	            char c = s.charAt(i);
18	            if (c < '0' || c > '9') {
19	                continue;
20	            }
21	            int d = c - '0';
22	            if (dbl) {
23	                d *= 2;
24	                if (d > 9) {
25	                    d -= 9;
26	                }
27	            }
28	            sum += d;
29	            dbl = !dbl;
30	        }
31	        return (10 - (sum % 10)) % 10;
32	    }
33	}
