1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from its city using a fixed
7	 * city-to-region table. Cities not in the table resolve to "UNKNOWN".
8	 */
9	final class Localities {
10	
11	    private static final Map<String, String> CITY_REGION = Map.of(
12	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
13	
14	    private Localities() {
15	    }
16	
17	    /** Canonical region for {@code city}, or "UNKNOWN" when it is not in the table. */
18	    static String regionOf(String city) {
19	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
20	    }
21	
22	    /**
23	     * Canonical region preferring the postcode range (NSW 2000-2099, VIC 3000-3099,
24	     * QLD 4000-4099); falls back to the city table when the postcode is absent or in
25	     * no known range.
26	     */
27	    static String regionOf(String city, String postcode) {
28	        String byPostcode = regionOfPostcode(postcode);
29	        return byPostcode != null ? byPostcode : regionOf(city);
30	    }
31	
32	    /** Region for a postcode's range, or {@code null} when absent or out of range. */
33	    private static String regionOfPostcode(String postcode) {
34	        Integer code = parse(postcode);
35	        if (code == null) {
36	            return null;
37	        }
38	        if (code >= 2000 && code <= 2099) {
39	            return "NSW";
40	        }
41	        if (code >= 3000 && code <= 3099) {
42	            return "VIC";
43	        }
44	        if (code >= 4000 && code <= 4099) {
45	            return "QLD";
46	        }
47	        return null;
48	    }
49	
50	    private static Integer parse(String postcode) {
51	        try {
52	            return postcode == null ? null : Integer.valueOf(postcode.trim());
53	        } catch (NumberFormatException ex) {
54	            return null;
55	        }
56	    }
57	}
