1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.MembershipLevels;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class, imports = MembershipLevels.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
24	    @Mapping(target = "checkDigit", expression = "java(CheckDigits.luhnOf(owner.getCustomerCode()))")
25	    @Mapping(target = "membershipLevel", expression = "java(MembershipLevels.levelOf(owner))")
26	    @Mapping(target = "locality", expression = "java(Localities.regionOf(owner.getCity(), owner.getPostcode()))")
27	    @Mapping(target = "contactPreference", expression = "java(ContactPreferences.preferenceOf(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    Owner toOwner(OwnerDto ownerDto);
31	
32	    @Mapping(target = "id", ignore = true)
33	    @Mapping(target = "pets", ignore = true)
34	    Owner toOwner(OwnerFieldsDto ownerDto);
35	
36	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
37	
38	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
39	
40	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
41	        OwnerPageDto ownerPageDto = new OwnerPageDto();
42	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
43	        ownerPageDto.setPage(ownerPage.getNumber());
44	        ownerPageDto.setSize(ownerPage.getSize());
45	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
46	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
47	        return ownerPageDto;
48	    }
49	}
