26	/**
27	 * Simple JavaBean domain object representing an owner.
28	 *
29	 * @author Ken Krebs
30	 * @author Juergen Hoeller
31	 * @author Sam Brannen
32	 * @author Michael Isvy
33	 */
34	@Entity
35	@Table(name = "owners")
36	@EntityListeners(OwnerAuditListener.class)
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be a valid E.164 number")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "household_member_count")
64	    private Integer householdMemberCount;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "registration_date")
70	    private java.time.LocalDate registrationDate;
71	
72	    @Column(name = "bulk_signup_warning")
73	    private Boolean bulkSignupWarning;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    @PrePersist
79	    private void defaultRegistrationDate() {
80	        if (this.registrationDate == null) {
81	            this.registrationDate = java.time.LocalDate.now();
82	        }
83	    }
84	
85	    public java.time.LocalDate getRegistrationDate() {
86	        return this.registrationDate;
87	    }
88	
89	    /** True when more than 80 owners were already created on this owner's registration date. */
90	    public Boolean getBulkSignupWarning() {
91	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
92	    }
93	
94	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
95	        this.bulkSignupWarning = bulkSignupWarning;
96	    }
97	
98	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
99	        this.registrationDate = registrationDate;
100	    }
101	
102	    public String getCustomerCode() {
103	        return this.customerCode;
104	    }
105	
106	    /**
107	     * Assign this owner's customerCode as '<CITY3>-<LAST3>-<NNNN>', where CITY3 and
108	     * LAST3 are the upper-cased first three letters of the city and last name and
109	     * NNNN is a 4-digit, zero-padded sequence one greater than the number of owners
110	     * already in this owner's city.
111	     */
112	    public void assignCustomerCode(int existingCityCount) {
113	        String city3 = this.city.substring(0, Math.min(3, this.city.length())).toUpperCase(Locale.ROOT);
114	        String last3 = this.lastName.substring(0, Math.min(3, this.lastName.length())).toUpperCase(Locale.ROOT);
115	        this.customerCode = String.format("%s-%s-%04d", city3, last3, existingCityCount + 1);
116	    }
117	
118	    public Integer getNamesakeCount() {
119	        return this.namesakeCount;
120	    }
121	
122	    public void setNamesakeCount(Integer namesakeCount) {
123	        this.namesakeCount = namesakeCount;
124	    }
125	
126	    public Integer getHouseholdMemberCount() {
127	        return this.householdMemberCount;
128	    }
129	
130	    public void setHouseholdMemberCount(Integer householdMemberCount) {
131	        this.householdMemberCount = householdMemberCount;
132	    }
133	
134	    public String getHouseholdId() {
135	        return this.householdId;
136	    }
137	
138	    public void setHouseholdId(String householdId) {
139	        this.householdId = householdId;
140	    }
141	
142	    public String getPostcode() {
143	        return this.postcode;
144	    }
145	
146	    public void setPostcode(String postcode) {
147	        this.postcode = postcode;
148	    }
149	
150	    public String getEmail() {
151	        return this.email;
152	    }
153	
154	    public void setEmail(String email) {
155	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
156	    }
157	
158	    public String getAddress() {
159	        return this.address;
160	    }
161	
162	    public void setAddress(String address) {
163	        this.address = PostalAddress.normalize(address);
164	    }
165	
166	    public String getCity() {
167	        return this.city;
168	    }
169	
170	    public void setCity(String city) {
171	        this.city = city;
172	    }
173	
174	    public String getTelephone() {
175	        return this.telephone;
176	    }
