16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * Normalises a raw telephone string to E.164 form.
20	 */
21	final class TelephoneNumber {
22	
23	    private TelephoneNumber() {
24	    }
25	
26	    /**
27	     * Convert a raw telephone number to E.164: keep a leading {@code '+'} and country
28	     * code when present; otherwise assume country code {@code '+61'} and drop a single
29	     * leading {@code '0'} from the national digits. Spaces, dashes and brackets are
30	     * stripped. Returns {@code null} for a {@code null} input.
31	     */
32	    static String toE164(String raw) {
33	        if (raw == null) {
34	            return null;
35	        }
36	        boolean international = raw.trim().startsWith("+");
37	        String digits = raw.replaceAll("\\D", "");
38	        if (international) {
39	            return "+" + digits;
40	        }
41	        if (digits.startsWith("0")) {
42	            digits = digits.substring(1);
43	        }
44	        return "+61" + digits;
45	    }
46	}
