16	package org.springframework.samples.petclinic.model;
17	
18	import java.util.Locale;
19	import java.util.Map;
20	
21	/**
22	 * Normalises a raw postal address: trims and collapses whitespace, upper-cases,
23	 * and expands common abbreviations ({@code ST->STREET}, {@code RD->ROAD},
24	 * {@code AVE->AVENUE}).
25	 */
26	final class PostalAddress {
27	
28	    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
29	
30	    private PostalAddress() {
31	    }
32	
33	    /** Returns {@code null} for a {@code null} input. */
34	    static String normalize(String raw) {
35	        if (raw == null) {
36	            return null;
37	        }
38	        StringBuilder sb = new StringBuilder();
39	        for (String word : raw.strip().split("\\s+")) {
40	            String upper = word.toUpperCase(Locale.ROOT);
41	            if (!sb.isEmpty()) {
42	                sb.append(' ');
43	            }
44	            sb.append(ABBREVIATIONS.getOrDefault(upper, upper));
45	        }
46	        return sb.toString();
47	    }
48	}
