2	
3	import java.nio.charset.StandardCharsets;
4	import java.util.Collection;
5	import java.util.List;
6	import java.util.Locale;
7	import java.util.UUID;
8	
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	/**
12	 * Household-identity rule for owners: two owners share a household when they have
13	 * the same last name and the same address, compared case-insensitively with
14	 * collapsed whitespace.
15	 */
16	final class Households {
17	
18	    private Households() {
19	    }
20	
21	    /**
22	     * Whether {@code candidate} duplicates the household of an existing owner and so
23	     * should be rejected. A {@code sharesHousehold} flag of {@code true} opts out.
24	     */
25	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
26	        if (Boolean.TRUE.equals(sharesHousehold)) {
27	            return false;
28	        }
29	        return existing.stream().anyMatch(other -> sameHousehold(other, candidate));
30	    }
31	
32	    /**
33	     * When {@code candidate} opts to share a household, stamp it and every existing
34	     * housemate with the same stable {@code householdId} and return the housemates so
35	     * the caller can persist them. Returns an empty list when nothing is shared.
36	     */
37	    static List<Owner> joinHousehold(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
38	        if (!Boolean.TRUE.equals(sharesHousehold)) {
39	            return List.of();
40	        }
41	        List<Owner> housemates = existing.stream().filter(other -> sameHousehold(other, candidate)).toList();
42	        if (!housemates.isEmpty()) {
43	            String householdId = householdId(candidate);
44	            candidate.setHouseholdId(householdId);
45	            candidate.setHouseholdMemberCount(housemates.size() + 1);
46	            housemates.forEach(mate -> mate.setHouseholdId(householdId));
47	        }
48	        return housemates;
49	    }
50	
51	    /** A stable identifier derived from the normalized household key, shared by all its members. */
52	    private static String householdId(Owner owner) {
53	        String key = normalize(owner.getLastName()) + "|" + normalize(owner.getAddress());
54	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
55	    }
56	
57	    private static boolean sameHousehold(Owner a, Owner b) {
58	        return normalize(a.getLastName()).equals(normalize(b.getLastName()))
59	            && normalize(a.getAddress()).equals(normalize(b.getAddress()));
60	    }
61	
62	    private static String normalize(String value) {
63	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
64	    }
65	}
