8	/**
9	 * Business-day rule for owner registration dates: the effective registration
10	 * date defaults to the server's current date when absent and, when it lands on
11	 * a weekend, rolls forward to the following Monday.
12	 */
13	final class BusinessDays {
14	
15	    private BusinessDays() {
16	    }
17	
18	    /** The owner's effective registration date, defaulted and rolled onto a business day. */
19	    static LocalDate effective(Owner owner) {
20	        LocalDate date = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
21	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
22	            date = date.plusDays(1);
23	        }
24	        return date;
25	    }
26	}
