### Locality / region derivation (city + postcode)
`/home/daniel/sandbox/src/main/java/org/springframework/samples/petclinic/mapper/Localities.java` (full file, lines 11-56)
```java
private static final Map<String, String> CITY_REGION = Map.of(
    "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

static String regionOf(String city) {
    return CITY_REGION.getOrDefault(city, "UNKNOWN");
}
static String regionOf(String city, String postcode) {
    String byPostcode = regionOfPostcode(postcode);
    return byPostcode != null ? byPostcode : regionOf(city);
}
private static String regionOfPostcode(String postcode) {
    Integer code = parse(postcode);
    if (code == null) { return null; }
    if (code >= 2000 && code <= 2099) { return "NSW"; }
    if (code >= 3000 && code <= 3099) { return "VIC"; }
    if (code >= 4000 && code <= 4099) { return "QLD"; }
    return null;
}
